create table public.diagnostic_submissions (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),student_name text not null check (char_length(student_name) between 2 and 120),class_name text not null check (char_length(class_name) between 1 and 40),group_name text not null default '' check (char_length(group_name)<=40),equipment_profile jsonb not null default '{}'::jsonb,answers jsonb not null check(jsonb_typeof(answers)='object'),domain_scores jsonb not null check(jsonb_typeof(domain_scores)='object'),score smallint not null check(score between 0 and 20),level text not null check(level in ('Remédiation prioritaire','Acquis à consolider','Acquis solides')),duration_seconds integer not null default 0 check(duration_seconds between 0 and 7200),quiz_version text not null default '2026-09',teacher_observation text not null default '' check(char_length(teacher_observation)<=2000));
create index diagnostic_submissions_created_at_idx on public.diagnostic_submissions(created_at desc); create index diagnostic_submissions_class_name_idx on public.diagnostic_submissions(class_name); alter table public.diagnostic_submissions enable row level security; grant usage on schema public to anon,authenticated; grant insert on table public.diagnostic_submissions to anon,authenticated; grant select,update,delete on table public.diagnostic_submissions to authenticated;
create policy "students_can_submit" on public.diagnostic_submissions for insert to anon,authenticated with check(char_length(student_name) between 2 and 120 and char_length(class_name) between 1 and 40 and score between 0 and 20);
-- Replace teacher@example.com with the authorized teacher account before applying.
create policy "teacher_can_read" on public.diagnostic_submissions for select to authenticated using((((select auth.jwt())->>'email')='teacher@example.com')); create policy "teacher_can_update" on public.diagnostic_submissions for update to authenticated using((((select auth.jwt())->>'email')='teacher@example.com')) with check((((select auth.jwt())->>'email')='teacher@example.com')); create policy "teacher_can_delete" on public.diagnostic_submissions for delete to authenticated using((((select auth.jwt())->>'email')='teacher@example.com'));
